function quickSort(a, l = 0, r = a.length - 1) {
  if (l >= r) return a;
  const p = partition(a, l, r);
  quickSort(a, l, p - 1);
  quickSort(a, p + 1, r);
  return a;
}

function partition(a, l, r) {
  // 随机化基准：随机选一个与末尾交换，规避有序数据最坏情况
  const ri = l + Math.floor(Math.random() * (r - l + 1));
  [a[ri], a[r]] = [a[r], a[ri]];
  const pivot = a[r];
  let i = l - 1;                 // 小于 pivot 区间的右边界
  for (let j = l; j < r; j++) {
    if (a[j] < pivot) {
      i++;
      [a[i], a[j]] = [a[j], a[i]];
    }
  }
  [a[i + 1], a[r]] = [a[r], a[i + 1]]; // 基准归位
  return i + 1;
}

